import{az as e,P as i,Q as l,aQ as t}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const A=JSON.parse('{"title":"你怎么看待AI","description":"","frontmatter":{},"headers":[],"relativePath":"AI/感受.md","filePath":"AI/感受.md","lastUpdated":1781716938000}'),r={name:"AI/感受.md"};function o(s,a,n,d,_,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="你怎么看待ai" tabindex="-1">你怎么看待AI <a class="header-anchor" href="#你怎么看待ai" aria-label="Permalink to “你怎么看待AI”">​</a></h1><ol><li>AI低版本信息滞后太多，想使用一些新技术根本用不成。 例如Chatgpt3.5 是24年左右发行的， 那么它对25年以后得信息根本无法检索， 一些技术在此后更新，AI还在使用旧版文档来处理信息。</li><li>大模型训练是通过公开训练的，对于垂直领域、非开源领域（医疗、法律）缺少数据训练，信息闭塞会影响回答内容的准确性</li><li>幻觉问题，在不擅长的领域可能会一本正经的胡说八道，如果你也一知半解，那么会导致结果偏差严重</li></ol><h2 id="写代码变成了写提示词" tabindex="-1">写代码变成了写提示词 <a class="header-anchor" href="#写代码变成了写提示词" aria-label="Permalink to “写代码变成了写提示词”">​</a></h2><p>在一个摇摇欲坠的地基上， 不过为了让它更稳定， 我们需要把控颗粒度， 不然很痛坍塌</p><ol><li>要保留文档</li></ol><h2 id="你和ai的区别" tabindex="-1">你和AI的区别 <a class="header-anchor" href="#你和ai的区别" aria-label="Permalink to “你和AI的区别”">​</a></h2><ul><li>对业务有更深层的了解、对相关领域业务更有经验，对使用ai产出业务代码时有更好的掌控。像代码技术圈是一个拥抱开源的氛围，但是有些行业并不拥抱开源，导致ai无法更好的收录，从事相关领域的业务无法达到更好的解决问题能力，给出的方案与实际业务脱离，这时是需要一个人来把控。</li><li>解决历史遗留问题，之前入职公司接手离职人员的老项目，项目用PHP跑的服务端渲染，前后端不分离，前后端共写一个项目，后端预留好模板入口、提供数据，前端使用模板语法和js进行页面渲染，使用的是jQuery和自定义的全局方法，例如点击表单按钮调用接口，但是这个全局方法是被混淆压缩的，根本找不到源码，没有文档、没有交接，想修改业务就只能看混淆后的代码，a、q、s等全是不明语义的名称， 只能通过打断点通过事件不断调试，硬着头皮进行修改。AI能做这些吗？可以做，但要花费很大的功夫引导，而且还不擅长。</li></ul>',7)])])}const m=e(r,[["render",o]]);export{A as __pageData,m as default};
